contracts/lib/ERC721Minimal.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

abstract contract ERC721Minimal {
    string public name;
    string public symbol;
    address public owner;

    mapping(uint256 => address) internal _owners;
    mapping(address => uint256) internal _balances;
    mapping(uint256 => string) internal _tokenURIs;

    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    constructor(string memory name_, string memory symbol_) {
        name = name_;
        symbol = symbol_;
        owner = msg.sender;
    }

    function balanceOf(address a) public view returns (uint256) {
        require(a != address(0), "zero");
        return _balances[a];
    }

    function ownerOf(uint256 tokenId) public view returns (address) {
        address o = _owners[tokenId];
        require(o != address(0), "not minted");
        return o;
    }

    function tokenURI(uint256 tokenId) public view returns (string memory) {
        require(_owners[tokenId] != address(0), "not minted");
        return _tokenURIs[tokenId];
    }

    function _setTokenURI(uint256 tokenId, string memory uri) internal {
        require(_owners[tokenId] != address(0), "not minted");
        _tokenURIs[tokenId] = uri;
    }

    function approve(address, uint256) public virtual {}
    function setApprovalForAll(address, bool) public virtual {}
    function transferFrom(address, address, uint256) public virtual {}
    function safeTransferFrom(address, address, uint256) public virtual {}
    function safeTransferFrom(address, address, uint256, bytes memory) public virtual {}

    function _mint(address to, uint256 tokenId) internal {
        require(to != address(0), "zero");
        require(_owners[tokenId] == address(0), "exists");
        _owners[tokenId] = to;
        _balances[to] += 1;
        emit Transfer(address(0), to, tokenId);
    }
}

contracts/RewardPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract RewardPool {
    address public owner;
    uint256 public totalPool;
    uint256 public start;
    uint256 public end;
    bytes public rule;

    event Deposited(address indexed sender, uint256 amount);
    event Configured(uint256 start, uint256 end, bytes rule);
    event Distributed(bytes32 indexed batchId, address[] creators, uint256[] amounts);

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function deposit() external payable {
        require(msg.value > 0, "no value");
        totalPool += msg.value;
        emit Deposited(msg.sender, msg.value);
    }

    function configure(uint256 _start, uint256 _end, bytes calldata _rule) external onlyOwner {
        require(_start < _end, "invalid period");
        start = _start;
        end = _end;
        rule = _rule;
        emit Configured(_start, _end, _rule);
    }

    function getSchedule() external view returns (uint256, uint256, bytes memory) {
        return (start, end, rule);
    }

    function distribute(address[] calldata creators, uint256[] calldata amounts) external onlyOwner {
        require(creators.length == amounts.length, "length mismatch");
        uint256 total;
        for (uint256 i = 0; i < amounts.length; i++) {
            total += amounts[i];
        }
        require(total <= totalPool, "exceeds pool");
        totalPool -= total;
        for (uint256 i = 0; i < creators.length; i++) {
            (bool ok, ) = creators[i].call{value: amounts[i]}("");
            require(ok, "transfer failed");
        }
        bytes32 batchId = keccak256(abi.encodePacked(block.number, creators.length, total));
        emit Distributed(batchId, creators, amounts);
    }
}

contracts/SoulboundBadge.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./lib/ERC721Minimal.sol";

contract SoulboundBadge is ERC721Minimal {
    address public minter;

    error Soulbound();

    constructor(string memory name_, string memory symbol_) ERC721Minimal(name_, symbol_) {
        minter = msg.sender;
    }

    modifier onlyMinter() {
        require(msg.sender == minter, "not minter");
        _;
    }

    function setMinter(address m) external onlyOwner {
        minter = m;
    }

    function mint(address to, uint256 tokenId, string memory uri) external onlyMinter {
        _mint(to, tokenId);
        _setTokenURI(tokenId, uri);
    }

    // disable transfers/approvals
    function approve(address, uint256) public pure override { revert Soulbound(); }
    function setApprovalForAll(address, bool) public pure override { revert Soulbound(); }
    function transferFrom(address, address, uint256) public pure override { revert Soulbound(); }
    function safeTransferFrom(address, address, uint256) public pure override { revert Soulbound(); }
    function safeTransferFrom(address, address, uint256, bytes memory) public pure override { revert Soulbound(); }
}

